using System.Text;using AuthService.Data;using AuthService.Services;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Serilog;Log.Logger=new LoggerConfiguration().WriteTo.Console().WriteTo.File("logs/auth-service-.log",rollingInterval:RollingInterval.Day).CreateLogger();var b=WebApplication.CreateBuilder(args);b.Host.UseSerilog();b.Services.AddControllers();b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen();b.Services.AddExceptionHandler<GlobalExceptionHandler>();b.Services.AddProblemDetails();b.Services.AddDbContext<AuthDbContext>(o=>o.UseNpgsql(b.Configuration.GetConnectionString("AuthDb")));var k=Encoding.UTF8.GetBytes(b.Configuration["Jwt:Key"]!);b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(k),RoleClaimType=System.Security.Claims.ClaimTypes.Role,NameClaimType=System.Security.Claims.ClaimTypes.Name});b.Services.AddAuthorization();b.Services.AddScoped<IAuthService,AuthService.Services.AuthService>();var a=b.Build();a.UseExceptionHandler();a.UseSwagger();a.UseSwaggerUI();a.UseAuthentication();a.UseAuthorization();a.MapControllers();a.Run();